'use strict';
const $=id=>document.getElementById(id);
const ipa={AA:'ɑ',AE:'æ',AH:'ʌ',AX:'ə',AO:'ɔ',AW:'aʊ',AY:'aɪ',B:'b',CH:'tʃ',D:'d',DH:'ð',EH:'ɛ',ER:'ɝ',EY:'eɪ',F:'f',G:'ɡ',HH:'h',IH:'ɪ',IY:'i',JH:'dʒ',K:'k',L:'l',M:'m',N:'n',NG:'ŋ',OW:'oʊ',OY:'ɔɪ',P:'p',R:'ɹ',S:'s',SH:'ʃ',T:'t',TH:'θ',UH:'ʊ',UW:'u',V:'v',W:'w',Y:'j',Z:'z',ZH:'ʒ'};
const maps={a:['AE','EY','AA','AO','AH','AX'],e:['EH','IY','IH','AX',''],i:['IH','AY','IY','AX'],o:['AA','OW','AO','AH','UH','AX'],u:['AH','UW','UH','Y UW','AX'],y:['Y','IY','AY','IH'],b:['B'],c:['K','S'],d:['D'],f:['F'],g:['G','JH'],h:['HH',''],j:['JH'],k:['K',''],l:['L'],m:['M'],n:['N','NG'],p:['P'],q:['K'],r:['R'],s:['S','Z','SH','ZH'],t:['T'],v:['V'],w:['W',''],x:['K S','G Z','Z'],z:['Z'],th:['TH','DH'],sh:['SH'],ch:['CH','K','SH'],ph:['F'],ng:['NG'],ck:['K'],qu:['K W'],wh:['W'],ee:['IY'],ea:['IY','EH','EY'],ai:['EY'],ay:['EY'],oa:['OW'],oe:['OW'],ow:['OW','AW'],ou:['AW','AH','UW','OW'],oo:['UW','UH'],oi:['OY'],oy:['OY'],au:['AO'],aw:['AO'],er:['ER'],ir:['ER'],ur:['ER'],ar:['AA R','ER'],or:['AO R','ER'],air:['EH R'],ear:['IH R','ER','EH R'],igh:['AY'],ie:['AY','IY'],ew:['UW','Y UW'],ue:['UW'],igh:['AY'],kn:['N'],wr:['R'],mb:['M'],tch:['CH'],dge:['JH'],tion:['SH AX N'],sion:['ZH AX N','SH AX N']};
for(const c of 'bdfglmnprstz')maps[c+c]=maps[c];
let dictionary={},current='this',phones=[],groups=[],run=0,ctx,audioBuffers={},activeSource;
const normalize=p=>p==='AH0'?'AX':p.replace(/[012]/g,'');
const audioVersion='stop-sounds-v3';
function align(word,ps){const memo=new Map();function rec(i,j){let key=i+':'+j;if(memo.has(key))return memo.get(key);if(i===word.length)return j===ps.length?{score:0,parts:[]}:null;let best=null;for(let size=1;size<=4 && i+size<=word.length;size++){let text=word.slice(i,i+size);for(const seq of maps[text]||[]){const codes=seq?seq.split(' '):[];if(codes.every((p,k)=>ps[j+k]===p)){let tail=rec(i+size,j+codes.length);if(tail){let score=tail.score+(codes.length?1:5);if(!best||score<best.score)best={score,parts:[{text,codes,start:j},...tail.parts]};}}}}memo.set(key,best);return best;}return rec(0,0)?.parts;}
function cancel(){run++;if(activeSource){try{activeSource.stop();}catch{}activeSource=null;}if('speechSynthesis'in window)speechSynthesis.cancel();document.querySelectorAll('.active').forEach(x=>x.classList.remove('active'));$('stop').hidden=true;}
async function unlock(){if(!ctx)ctx=new (window.AudioContext||window.webkitAudioContext)();await ctx.resume();}
function playBuffer(buffer,token){if(token!==run)return Promise.resolve();let peak=0;for(let channel=0;channel<buffer.numberOfChannels;channel++){const data=buffer.getChannelData(channel);for(let i=0;i<data.length;i++)peak=Math.max(peak,Math.abs(data[i]));}if(!peak)throw Error('This audio sample is silent. Please try again.');const gain=ctx.createGain();gain.gain.value=.75/peak;return new Promise(resolve=>{const src=ctx.createBufferSource();src.buffer=buffer;src.connect(gain);gain.connect(ctx.destination);activeSource=src;src.onended=()=>{if(activeSource===src)activeSource=null;resolve();};src.start();});}
async function sound(code,token){await unlock();if(!audioBuffers[code]){const r=await fetch('audio/'+code+'.wav?v='+audioVersion);if(!r.ok)throw Error('Sound unavailable');audioBuffers[code]=await ctx.decodeAudioData(await r.arrayBuffer());}return playBuffer(audioBuffers[code],token);}
async function say(word,token){if((dictionary[word]?.length||0)>1){await unlock();const r=await fetch('words/'+word+'-'+Number($('variants').value||0)+'.mp3?v='+audioVersion);if(!r.ok)throw Error('This pronunciation audio could not load. Try again.');const b=await ctx.decodeAudioData(await r.arrayBuffer());return playBuffer(b,token);}return new Promise((resolve,reject)=>{if(token!==run)return resolve();if(!('speechSynthesis'in window))return reject(Error('Word audio is not supported in this browser.'));const u=new SpeechSynthesisUtterance(word);u.lang='en-US';u.rate=.8;const voice=speechSynthesis.getVoices().find(v=>v.lang==='en-US');if(voice)u.voice=voice;u.onend=resolve;u.onerror=e=>e.error==='canceled'||e.error==='interrupted'?resolve():reject(Error('Could not play the word. Try again.'));speechSynthesis.speak(u);});}
function mark(i){document.querySelectorAll('.tile').forEach((x,k)=>x.classList.toggle('active',k===i));}
function render(variant=0){cancel();phones=(dictionary[current]?.[variant]||[]).map(normalize);const aligned=align(current,phones);groups=aligned||phones.map((p,i)=>({text:ipa[p],codes:[p],start:i}));$('word').textContent=current;$('tiles').replaceChildren();groups.forEach((g,i)=>{const b=document.createElement('button');b.className='tile'+(g.codes.length?'':' silent');b.disabled=!g.codes.length;b.type='button';const t=document.createElement('strong');t.textContent=g.text;const s=document.createElement('small');s.textContent=g.codes.length?'/'+g.codes.map(p=>ipa[p]).join(' ')+'/':'silent';b.append(t,s);b.setAttribute('aria-label',g.codes.length?'Hear '+g.text+' sound':'Silent '+g.text);b.onclick=async()=>{cancel();const token=run;mark(i);try{for(const p of g.codes)await sound(p,token);}catch(e){$('status').textContent=e.message;}if(token===run)mark(-1);};$('tiles').append(b);});$('count').textContent=phones.length?phones.length+' sounds · '+(dictionary[current]?.[variant].filter(p=>/[012]/.test(p)).length||1)+' syllable(s)':'';$('segment').disabled=$('blend').disabled=!phones.length;$('status').textContent=!phones.length?'This word is not in our dictionary. You can still try Hear word.':aligned?'Ready. Listen, then try it yourself.':'Sound cards shown as phonetic symbols. Letter grouping needs a parent’s review.';}
function setWord(word){if(typeof word!=='string'||!/^[a-zA-Z]{1,40}$/.test(word.trim()))throw Error('Please enter one English word using letters only.');current=word.trim().toLowerCase();$('input').value=current;const variants=dictionary[current]||[];$('variants').replaceChildren();variants.forEach((p,i)=>{const o=document.createElement('option');o.value=i;o.textContent='/'+p.map(normalize).map(x=>ipa[x]).join(' ')+'/';$('variants').append(o);});$('variantLabel').hidden=variants.length<2;const preferred=current==='read'?1:0;$('variants').value=String(Math.min(preferred,Math.max(variants.length-1,0)));render(Number($('variants').value));return{word:current,phonemes:phones,letterGroups:groups};}
async function sequence(blend){cancel();const token=run;$('stop').hidden=false;try{await unlock();for(let i=0;i<groups.length;i++){if(token!==run)return;mark(i);for(const p of groups[i].codes)await sound(p,token);if(token!==run)return;await new Promise(r=>setTimeout(r,blend?35:280));}if(token!==run)return;mark(-1);if(blend){$('status').textContent='Together: '+current;await say(current,token);}if(token===run)$('status').textContent='Your turn! Say the word.';}catch(e){if(token===run)$('status').textContent=e.message;}finally{if(token===run){mark(-1);$('stop').hidden=true;}}}
$('form').onsubmit=e=>{e.preventDefault();try{setWord($('input').value);}catch(e){$('status').textContent=e.message;}};$('variants').onchange=()=>render(Number($('variants').value));$('whole').onclick=async()=>{cancel();const token=run;$('stop').hidden=false;try{await say(current,token);}catch(e){$('status').textContent=e.message;}if(token===run)$('stop').hidden=true;};$('segment').onclick=()=>sequence(false);$('blend').onclick=()=>sequence(true);$('stop').onclick=()=>{cancel();$('status').textContent='Paused. Tap to try again.';};document.querySelectorAll('.examples button').forEach(b=>b.onclick=()=>setWord(b.textContent));
$('segment').disabled=$('blend').disabled=$('go').disabled=true;
fetch('dictionary.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(d=>{dictionary=d;$('go').disabled=false;setWord('this');}).catch(()=>{$('status').textContent='Dictionary could not load. Reload this page to try again.';});
if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'set_practice_word',description:'Show a single English word and its pronunciation for phonics practice.',inputSchema:{type:'object',properties:{word:{type:'string'}},required:['word'],additionalProperties:false},execute:input=>{if(!Object.keys(dictionary).length)throw Error('Dictionary is still loading');return setWord(input.word);}}, {signal:life.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
